public void clicked()
{
    Args args = new Args();
    FormControl ctrl = this;
    args.caller(ctrl.formRun());

    PurchLine purchLine =  ctrl.formRun().dataSource(formDataSourceStr(PurchTable, PurchLine)).cursor();
    args.record(purchLine);

    if (args.record() && args.caller())
    {
        METISPPurchLineStripDelete::main(args);
    }

    next clicked();
}
